const whStatuses=[['concluida','Concluída'],['nao_cliente','Não cliente'],['nao_localizado','Não localizado'],['nao_encontrado','Não encontrado'],['erro','Erro'],['revisao','Revisão'],['interrompida','Consulta interrompida']];
let webhookRows=[],webhookEditing=null,webhookTab='api',webhookBusy=false,webhookLoading=false,webhookGeneration=0;
const whRoot=$('#settings-integrations'),whApi=document.createElement('div');whApi.id='integration-api';while(whRoot.firstChild)whApi.appendChild(whRoot.firstChild);whRoot.appendChild(whApi);
const whTabs=document.createElement('div');whTabs.className='integration-tabs';whTabs.setAttribute('aria-label','Integrações');whTabs.innerHTML='<button type="button" data-integration="api" aria-pressed="true">API e tokens</button><button type="button" data-integration="webhooks" aria-pressed="false">Webhooks</button>';whRoot.prepend(whTabs);
const whPanel=document.createElement('div');whPanel.id='integration-webhooks';whPanel.hidden=true;whPanel.innerHTML=`
<section class="card"><div class="heading"><div><span class="section-kicker">RESULTADOS EM TEMPO REAL</span><h2>Webhooks</h2><p>Envie os resultados para seu CRM, n8n ou outro sistema, sem atrasar as consultas.</p></div><button type="button" id="whNew" class="primary">Novo webhook</button></div><p id="whStatus" role="status" aria-live="polite"></p><div id="whList"><p>Nenhum webhook carregado.</p></div></section>
<section class="card" id="whEditor" hidden><div class="heading"><h2 id="whEditorTitle">Novo webhook</h2><button type="button" id="whCancel">Cancelar</button></div><form id="whForm">
<div class="two"><div><label class="field" for="whName">Nome da integração</label><input id="whName" required maxlength="100" placeholder="Ex.: CRM comercial"></div><div><label class="field" for="whUrl">URL de destino (HTTPS)</label><input id="whUrl" type="url" required maxlength="2048" placeholder="https://seu-sistema.com/webhook"></div></div>
<h3>1. De onde vêm os resultados?</h3><div class="two"><div><label class="field" for="whScope">Origem</label><select id="whScope"><option value="all">Individuais e campanhas</option><option value="individual">Somente individuais</option><option value="campaign">Uma campanha específica</option></select></div><div id="whServiceWrap"><label class="field" for="whService">Tipo de consulta</label><select id="whService"><option value="">Todos os tipos</option><option value="digimais_saldo_parcela">Digi+ · Saldo e parcela</option><option value="tjba_margem">ConsigX · Margem</option></select></div><div id="whCampaignWrap" hidden><label class="field" for="whCampaign">Campanha</label><select id="whCampaign"></select></div></div>
<h3>2. Quando enviar?</h3><fieldset class="wh-checks"><legend>Eventos</legend><label><input type="checkbox" id="whQueryEvent" checked> Ao finalizar cada consulta de CPF</label><label id="whSummaryLabel"><input type="checkbox" id="whSummaryEvent"> Ao finalizar a campanha (relatório)</label></fieldset>
<div id="whQueryFilters"><fieldset class="wh-checks"><legend>Status da consulta — escolha um ou mais</legend>${whStatuses.map(([v,l])=>`<label><input type="checkbox" name="whStatusFilter" value="${v}" checked> ${l}</label>`).join('')}</fieldset><label class="field" for="whClient">Identificação do cliente</label><select id="whClient"><option value="all">Qualquer resultado</option><option value="client">Cliente identificado</option><option value="nonclient">Não cliente / não localizado</option><option value="unknown">Indeterminado (sem confirmação)</option></select><label class="wh-check"><input type="checkbox" id="whPartial" checked> Incluir resultados parciais</label><p class="muted">Os filtros se combinam. Ex.: escolha Revisão + Cliente identificado para receber falhas com saldo ou parcela já obtidos. No Digi+, o envio ocorre após a consulta de saldo e parcela terminar.</p></div>
<p class="muted" id="whSummaryNote" hidden>O relatório final usa apenas a origem e o tipo de consulta. Os filtros de status e cliente se aplicam aos eventos de CPF.</p><label class="wh-check"><input type="checkbox" id="whActive" checked> Webhook ativo</label><div class="actions"><button class="primary" id="whSave">Salvar webhook</button></div></form></section>
<section class="card api-new-token" id="whSecretPanel" hidden><h2>Guarde o segredo de assinatura</h2><p>Ele aparece apenas agora. Use-o para validar os envios no seu sistema. Não é a chave do Supabase.</p><input id="whSecret" type="password" readonly autocomplete="off" aria-label="Segredo de assinatura recém-gerado"><div class="actions"><button type="button" id="whCopySecret">Copiar segredo</button><button type="button" id="whShowSecret">Mostrar</button><button type="button" id="whDismissSecret">Já guardei</button></div></section>
<section class="card"><div class="heading"><div><h2>Histórico de entregas</h2><p>Últimas 50 entregas da sua conta. Atualização automática enquanto esta aba estiver aberta.</p></div><button type="button" id="whRefresh">Atualizar</button></div><label class="field" for="whHistoryHook">Integração</label><select id="whHistoryHook"><option value="">Todas</option></select><div id="whHistory"></div></section>
<section class="card"><details><summary>Como integrar e validar os envios</summary><div class="wh-doc"><p>O envio é um <strong>POST JSON</strong>. Responda com HTTP 2xx rapidamente e processe o evento em sua própria fila. Use <code>event_id</code> para evitar processar o mesmo evento duas vezes.</p><p>A assinatura está no cabeçalho <code>X-ApoiarCred-Signature</code>: <code>v1=HMAC-SHA256(segredo, timestamp + "." + corpo original)</code>. O timestamp vem em <code>X-ApoiarCred-Timestamp</code>. Valide a assinatura com comparação segura e aceite apenas timestamps recentes (até 5 minutos).</p><pre id="whExample"></pre><p>Eventos: <code>consulta.finalizada</code>, <code>campanha.finalizada</code> e <code>webhook.teste</code>. O teste usa dados fictícios e ignora os filtros.</p><p>Até 8 tentativas em falhas de rede, HTTP 408, 425, 429 ou 5xx. Os intervalos são 30 s, 2 min, 10 min, 30 min, 2 h, 6 h e 12 h. Outros códigos, inclusive redirecionamentos, encerram a entrega.</p><p>A URL e o segredo atuais são usados nas próximas tentativas. Pausar interrompe novos disparos e a retirada de itens da fila; envios em andamento podem terminar. Reenvios mantêm o mesmo event_id. Cada conta vê somente seus webhooks e resultados.</p><p>São enviados somente novos resultados após a ativação. Uma campanha pode gerar outro relatório quando uma nova rodada de consultas ou revisões terminar. Máximo: 20 webhooks por conta e 10 testes/reenvios manuais por hora por webhook.</p></div></details></section>`;whRoot.appendChild(whPanel);
$('#whExample').textContent=JSON.stringify({event_id:'uuid-do-evento',event:'consulta.finalizada',occurred_at:'2026-11-05T12:00:00Z',campanha:{id:'uuid-da-campanha',nome:'Campanha de exemplo'},consulta:{id:'uuid-da-consulta',referencia_externa:null,servico:'digimais_saldo_parcela',convenio:null,cpf:'00000000000',nome:'Cliente fictício',telefone:'00000000000',status:'concluida',cliente_identificado:true,resultado_parcial:false,mensagem:null,resultado:{saldo_liquidacao:1000,valor_parcela:100,total_parcelas:96}}},null,2);
function switchIntegration(id){webhookTab=id;whApi.hidden=id!=='api';whPanel.hidden=id!=='webhooks';for(const b of whTabs.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.integration===id));if(id==='webhooks'&&hasIntegrationAccess())loadWebhooks();}
whTabs.onclick=e=>{const b=e.target.closest('[data-integration]');if(b)switchIntegration(b.dataset.integration);};
const whOriginalSwitchSettings=switchSettings;switchSettings=function(id){whOriginalSwitchSettings(id);if(id==='integrations'&&webhookTab==='webhooks')loadWebhooks();};
function whRpc(action,input={}){return sbRequest('/rest/v1/rpc/manage_webhooks',{method:'POST',body:JSON.stringify({p_action:action,p_input:input})});}
function whClearSecret(){$('#whSecret').value='';$('#whSecret').type='password';$('#whSecretPanel').hidden=true;$('#whShowSecret').textContent='Mostrar';}
function resetWebhooks(){webhookGeneration++;webhookRows=[];webhookEditing=null;webhookBusy=false;whClearSecret();$('#whEditor').hidden=true;$('#whList').innerHTML='';$('#whHistory').innerHTML='';$('#whStatus').textContent='';$('#whForm').reset();switchIntegration('api');}
function whShowSecret(secret){if(!secret)return;$('#whSecret').value=secret;$('#whSecretPanel').hidden=false;$('#whSecretPanel').scrollIntoView({behavior:'smooth',block:'center'});}
$('#whCopySecret').onclick=()=>copyApi($('#whSecret').value);$('#whDismissSecret').onclick=whClearSecret;$('#whShowSecret').onclick=()=>{const hidden=$('#whSecret').type==='password';$('#whSecret').type=hidden?'text':'password';$('#whShowSecret').textContent=hidden?'Ocultar':'Mostrar';};
function whDate(value){return value?new Date(value).toLocaleString('pt-BR'):'—';}
function whOrigin(w){return w.scope==='campaign'?'Campanha: '+(campaigns.find(c=>c.id===w.campaign_id)?.nome||w.campaign_id):w.scope==='individual'?'Consultas individuais':'Individuais e campanhas';}
function whRenderList(){
 $('#whList').innerHTML=webhookRows.length?webhookRows.map(w=>`<article class="wh-row"><div class="heading"><div><strong>${escapeHTML(w.name)}</strong> <span class="pill ${w.active?'ok':''}">${w.active?'Ativo':'Pausado'}</span><p class="wh-url">${escapeHTML(w.url)}</p><p>${escapeHTML(whOrigin(w))} · ${escapeHTML(w.service==='digimais_saldo_parcela'?'Digi+':w.service==='tjba_margem'?'ConsigX':'Todos os tipos')}</p><small>${escapeHTML(w.events.join(' · '))}</small></div><div class="actions"><button type="button" data-wh-action="edit" data-id="${w.id}">Editar</button><button type="button" data-wh-action="toggle" data-id="${w.id}">${w.active?'Pausar':'Ativar'}</button><button type="button" data-wh-action="test" data-id="${w.id}" ${w.active?'':'disabled'}>Enviar teste</button><button type="button" data-wh-action="rotate" data-id="${w.id}">Trocar segredo</button></div></div></article>`).join(''):'<div class="wh-empty"><h3>Receba os resultados no seu sistema</h3><p>Crie um webhook, escolha a campanha ou origem e defina quais resultados deseja receber.</p></div>';
 const selected=$('#whHistoryHook').value;$('#whHistoryHook').innerHTML='<option value="">Todas</option>'+webhookRows.map(w=>`<option value="${w.id}">${escapeHTML(w.name)}</option>`).join('');if(webhookRows.some(w=>w.id===selected))$('#whHistoryHook').value=selected;
}
function whRenderHistory(rows){
 const labels={pending:'Na fila',delivering:'Enviando',retry:'Nova tentativa agendada',delivered:'Entregue',failed:'Falhou'};
 $('#whHistory').innerHTML=rows.length?rows.map(d=>`<article class="wh-row"><div class="heading"><div><strong>${escapeHTML(d.hook_name)}</strong> <span class="pill ${d.state==='delivered'?'ok':''}">${labels[d.state]||escapeHTML(d.state)}</span><p>${escapeHTML(d.event)}${d.cpf?' · CPF '+escapeHTML(d.cpf):''}${d.campaign_name?' · '+escapeHTML(d.campaign_name):''}</p><small>${whDate(d.created_at)} · HTTP ${d.last_http||'—'} · ${d.total_attempts} tentativa(s)${d.state==='retry'?' · Próxima: '+whDate(d.next_at):''}</small>${d.last_error?`<p class="error">${escapeHTML(d.last_error)}</p>`:''}</div>${['delivered','failed'].includes(d.state)?`<button type="button" data-wh-retry="${d.id}">Reenviar</button>`:''}</div><details><summary>Detalhes de entrega</summary><p>ID do evento: <code>${escapeHTML(d.event_id)}</code></p>${d.attempts_log.map(a=>`<p>Tentativa ${a.attempt} · ${whDate(a.started_at)} · HTTP ${a.http_status||'—'} · ${escapeHTML(a.error|| (a.finished_at?'Finalizada':'Em andamento'))}</p>`).join('')||'<p>Aguardando primeira tentativa.</p>'}</details></article>`).join(''):'<p class="wh-empty">Nenhuma entrega para este filtro. Envie um teste ou aguarde a próxima consulta.</p>';
}
async function loadWebhooks(){
 if(!authenticated||!hasIntegrationAccess()||webhookLoading)return;webhookLoading=true;const epoch=authEpoch,generation=webhookGeneration,hook_id=$('#whHistoryHook').value;
 try{const [rows,history]=await Promise.all([whRpc('list'),whRpc('history',{hook_id})]);if(epoch!==authEpoch||generation!==webhookGeneration||!hasIntegrationAccess())return;webhookRows=rows;whRenderList();if(hook_id===$('#whHistoryHook').value)whRenderHistory(history);}
 catch(e){if(epoch===authEpoch&&generation===webhookGeneration)$('#whStatus').textContent='Não foi possível carregar os webhooks. '+e.message;}
 finally{webhookLoading=false;}
}
function whScopeChanged(){const campaign=$('#whScope').value==='campaign',individual=$('#whScope').value==='individual';$('#whCampaignWrap').hidden=!campaign;$('#whServiceWrap').hidden=campaign;$('#whSummaryLabel').hidden=individual;if(individual)$('#whSummaryEvent').checked=false;whFiltersChanged();}
function whFiltersChanged(){$('#whQueryFilters').hidden=!$('#whQueryEvent').checked;$('#whSummaryNote').hidden=!$('#whSummaryEvent').checked;}
$('#whScope').onchange=whScopeChanged;$('#whQueryEvent').onchange=whFiltersChanged;$('#whSummaryEvent').onchange=whFiltersChanged;
function whEdit(w=null,campaignId=null){
 if(!$('#whSecretPanel').hidden){toast('Guarde o segredo atual e clique em Já guardei.');return;}
 webhookEditing=w?.id||null;$('#whForm').reset();$('#whEditorTitle').textContent=w?'Editar webhook':'Novo webhook';$('#whCampaign').innerHTML=campaigns.map(c=>`<option value="${c.id}">${escapeHTML(c.nome)} · ${escapeHTML(c.servico==='tjba_margem'?'ConsigX':'Digi+')}</option>`).join('');
 if(w){$('#whName').value=w.name;$('#whUrl').value=w.url;$('#whScope').value=w.scope;$('#whService').value=w.service||'';$('#whCampaign').value=w.campaign_id||'';$('#whQueryEvent').checked=w.events.includes('consulta.finalizada');$('#whSummaryEvent').checked=w.events.includes('campanha.finalizada');$('#whClient').value=w.client_filter;$('#whPartial').checked=w.include_partial;$('#whActive').checked=w.active;for(const el of document.querySelectorAll('[name="whStatusFilter"]'))el.checked=w.statuses.includes(el.value);}
 if(campaignId){$('#whScope').value='campaign';$('#whCampaign').value=campaignId;}whScopeChanged();$('#whEditor').hidden=false;$('#whEditor').scrollIntoView({behavior:'smooth',block:'start'});$('#whName').focus();
}
$('#whNew').onclick=()=>whEdit();$('#whCancel').onclick=()=>{$('#whEditor').hidden=true;webhookEditing=null;};
async function whMutate(button,fn,onSuccess){if(webhookBusy||!hasIntegrationAccess())return;webhookBusy=true;button.disabled=true;const epoch=authEpoch,generation=webhookGeneration;try{const r=await fn();if(epoch!==authEpoch||generation!==webhookGeneration||!hasIntegrationAccess())return;if(onSuccess)onSuccess(r);if(r?.secret)whShowSecret(r.secret);await loadWebhooks();}catch(e){if(epoch===authEpoch&&generation===webhookGeneration)$('#whStatus').textContent=e.message;}finally{webhookBusy=false;button.disabled=false;}}
$('#whForm').onsubmit=e=>{e.preventDefault();const events=[];if($('#whQueryEvent').checked)events.push('consulta.finalizada');if($('#whSummaryEvent').checked)events.push('campanha.finalizada');const statuses=[...document.querySelectorAll('[name="whStatusFilter"]:checked')].map(x=>x.value),scope=$('#whScope').value;let url;
 try{url=new URL($('#whUrl').value);if(url.protocol!=='https:'||url.username||url.password||url.hash||url.port&&url.port!=='443')throw Error();}catch{$('#whStatus').textContent='Use uma URL HTTPS pública, na porta 443, sem usuário, senha ou fragmento.';return;}
 if(!events.length||$('#whQueryEvent').checked&&!statuses.length){$('#whStatus').textContent='Escolha ao menos um evento e um status para os eventos de consulta.';return;}if(scope==='campaign'&&!$('#whCampaign').value){$('#whStatus').textContent='Selecione uma campanha.';return;}
 whMutate($('#whSave'),async()=>{const r=await whRpc(webhookEditing?'update':'create',{id:webhookEditing,name:$('#whName').value.trim(),url:url.href,active:$('#whActive').checked,scope,service:$('#whService').value,campaign_id:scope==='campaign'?$('#whCampaign').value:null,events,statuses:statuses.length?statuses:whStatuses.map(x=>x[0]),client_filter:$('#whClient').value,include_partial:$('#whPartial').checked});return r;},()=>{$('#whEditor').hidden=true;$('#whStatus').textContent='Webhook salvo. Somente novos resultados serão enviados.';});
};
$('#whList').onclick=e=>{const b=e.target.closest('[data-wh-action]');if(!b)return;const w=webhookRows.find(w=>w.id===b.dataset.id);if(!w)return;const action=b.dataset.whAction;if(action==='edit'){whEdit(w);return;}if(action==='rotate'&&!$('#whSecretPanel').hidden){toast('Guarde o segredo atual primeiro.');return;}if(action==='rotate'&&!confirm('Trocar o segredo? Atualize a validação no destino. Próximos envios, inclusive os já na fila, usarão o novo segredo.'))return;whMutate(b,()=>whRpc(action,{id:w.id,active:!w.active}),()=>{$('#whStatus').textContent=action==='test'?'Teste fictício colocado na fila. Acompanhe a entrega abaixo.':action==='rotate'?'Segredo alterado. Copie e atualize o destino.':w.active?'Webhook pausado. Envios em andamento podem terminar.':'Webhook ativado.';});};
$('#whHistory').onclick=e=>{const b=e.target.closest('[data-wh-retry]');if(b&&confirm('Reenviar este evento com a URL e o segredo atuais? O destino deve evitar duplicações usando event_id.'))whMutate(b,()=>whRpc('retry',{delivery_id:b.dataset.whRetry}),()=>{$('#whStatus').textContent='Reenvio colocado na fila.';});};
$('#whRefresh').onclick=loadWebhooks;$('#whHistoryHook').onchange=loadWebhooks;
setInterval(()=>{if(authenticated&&hasIntegrationAccess()&&webhookTab==='webhooks'&&currentPage==='settings'&&!$('#settings-integrations').hidden&&!document.hidden)loadWebhooks();},5000);
